rule.example:

struct Fo;
trait Ab {}
enum X { A }


struct Something {
    q: i32, // VIOLATION - Field
}
fn main(xs: i32) { // VIOLATION - Parameter
    let r = 20; // VIOLATION - Local
    for i in 0..10 { // Not a violation (for binder)
        let _ = (i, r, xs);
    }
}


struct Something {
    really_long_int_name_var: i32, // VIOLATION - Field
}
fn main(interesting_arguments_list: i32) { // VIOLATION - Parameter
    let other_really_long_name = -5; // VIOLATION - Local
    let _ = (interesting_arguments_list, other_really_long_name);
}


struct ShortMethod;
impl ShortMethod {
    fn a(&self, index: i32) { // Violation
        let _ = index;
    }
}


struct Foo;
impl Foo {
    fn get_foo(&self) -> bool { true } // bad
    fn is_foo(&self) -> bool { true }  // ok
    fn get_foo_flag(&self, bar: i32) -> bool { bar > 0 } // ok unless checkParameterizedMethods=true
}
